/**
 * The planet view's look, as numbers: its colour grade and its focus. The view
 * (planetView.ts) reads the world's hints with these; the pass
 * (gradeFocusChunk.ts) does the same arithmetic per pixel, with these
 * constants.
 *
 * The grade is a look-up table the world gives, in the `.cube` format: a
 * plain-text 3D table that every grading tool writes (Resolve, Photoshop,
 * Affinity, Premiere, OpenColorIO). It maps each colour the view shows, after
 * its exposure, to the colour the world wants there. Laid out for the
 * graphics card as a strip of its blue slices side by side, each slice red
 * across and green down.
 *
 * The focus softens the far ground as the eye rises: nothing within a few
 * times the eye's height over the ground, and more the further past that,
 * as a lens focused on the ground below would. Standing or walking, the eye
 * is too low for any of it, so what the visitor stands on and looks at is
 * never blurred.
 *
 * Pure: no Babylon, no DOM.
 */

export type Vec3 = [number, number, number];

/** The focus's constants. */
export const FOCUS = {
  /** The eye's height over the ground, in metres, below which nothing is softened, and from which the softening is whole. */
  fromM: 24,
  fullM: 160,
  /** Where the focus lies, as a multiple of the eye's height over the ground: nearer than this is sharp. */
  perHeight: 2,
  /** The widest blur, in pixels across its radius, on a view this many pixels tall; a taller view widens it in step. */
  maxPx: 4.5,
  referenceHeightPx: 1080,
} as const;

/** The largest table accepted, along each edge: 64 is what grading tools write at most. */
export const MAX_CUBE_SIZE = 64;

/** A 3D look-up table: its size along each edge, the colours it covers, and its entries as red, green, blue triples, red changing fastest. */
export interface CubeLut {
  size: number;
  domainMin: Vec3;
  domainMax: Vec3;
  data: Float32Array;
}

type HintReader = (name: string) => string | null | undefined;

const clamp = (x: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, x));

/**
 * A `.cube` file's table: `LUT_3D_SIZE`, optional `DOMAIN_MIN` and
 * `DOMAIN_MAX`, `TITLE` and `#` comments, then size³ lines of three numbers.
 * A 1D table, a size out of range or a wrong count of entries is refused,
 * with the reason.
 */
export function parseCube(text: string): { ok: true; lut: CubeLut } | { ok: false; reason: string } {
  let size = 0;
  const domainMin: Vec3 = [0, 0, 0];
  const domainMax: Vec3 = [1, 1, 1];
  let data: Float32Array | null = null;
  let n = 0;
  const triple = (parts: string[]): Vec3 | null => {
    if (parts.length !== 3) return null;
    const v = parts.map(Number);
    return v.every(Number.isFinite) ? (v as Vec3) : null;
  };
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trim();
    if (line === '' || line.startsWith('#')) continue;
    const parts = line.split(/\s+/);
    const key = parts[0]!;
    if (/^[A-Za-z_]/.test(key)) {
      if (data && n > 0) return { ok: false, reason: `a keyword among the entries: ${key}` };
      if (key === 'TITLE') continue;
      if (key === 'LUT_1D_SIZE') return { ok: false, reason: 'a 1D table; only 3D tables are read' };
      if (key === 'LUT_3D_SIZE') {
        size = Number(parts[1]);
        if (!Number.isInteger(size) || size < 2 || size > MAX_CUBE_SIZE) return { ok: false, reason: `LUT_3D_SIZE ${parts[1]} is not between 2 and ${MAX_CUBE_SIZE}` };
        data = new Float32Array(size * size * size * 3);
        continue;
      }
      if (key === 'DOMAIN_MIN' || key === 'DOMAIN_MAX') {
        const v = triple(parts.slice(1));
        if (!v) return { ok: false, reason: `${key} is not three numbers` };
        (key === 'DOMAIN_MIN' ? domainMin : domainMax).splice(0, 3, ...v);
        continue;
      }
      // Other keywords some tools write (LUT_IN_VIDEO_RANGE and the like) say nothing the table needs.
      continue;
    }
    if (!data) return { ok: false, reason: 'entries before LUT_3D_SIZE' };
    const v = triple(parts);
    if (!v) return { ok: false, reason: `an entry that is not three numbers: ${line.slice(0, 40)}` };
    if (n >= size * size * size) return { ok: false, reason: `more than ${size}³ entries` };
    data.set(v, n * 3);
    n++;
  }
  if (!data) return { ok: false, reason: 'no LUT_3D_SIZE' };
  if (n !== size * size * size) return { ok: false, reason: `${n} entries, not ${size}³` };
  if (domainMin.some((m, i) => !(domainMax[i]! > m))) return { ok: false, reason: 'DOMAIN_MAX is not above DOMAIN_MIN' };
  return { ok: true, lut: { size, domainMin, domainMax, data } };
}

/**
 * The table as the pass reads it: an image size² wide and size tall, red,
 * green, blue and alpha bytes, each blue slice side by side, red across it
 * and green down. Entries are held between 0 and 1.
 */
export function cubeStrip(lut: CubeLut): { width: number; height: number; pixels: Uint8Array } {
  const s = lut.size;
  const width = s * s;
  const pixels = new Uint8Array(width * s * 4);
  for (let b = 0; b < s; b++) {
    for (let g = 0; g < s; g++) {
      for (let r = 0; r < s; r++) {
        const from = ((b * s + g) * s + r) * 3;
        const to = (g * width + b * s + r) * 4;
        for (let c = 0; c < 3; c++) pixels[to + c] = Math.round(255 * clamp(lut.data[from + c]!, 0, 1));
        pixels[to + 3] = 255;
      }
    }
  }
  return { width, height: s, pixels };
}

/**
 * A colour through the table, as the pass looks it up: within the table's
 * colours, between the two blue slices about it, each read between its four
 * entries about the colour. For tests and for a reader of the pass.
 */
export function gradeColour(lut: CubeLut, c: Vec3): Vec3 {
  const s = lut.size;
  const at = (r: number, g: number, b: number, k: number) => lut.data[((b * s + g) * s + r) * 3 + k]!;
  const p = c.map((x, i) => clamp((x - lut.domainMin[i]!) / (lut.domainMax[i]! - lut.domainMin[i]!), 0, 1) * (s - 1)) as Vec3;
  const lo = p.map((x) => Math.min(Math.floor(x), s - 2)) as Vec3;
  const t = p.map((x, i) => x - lo[i]!) as Vec3;
  const out: Vec3 = [0, 0, 0];
  for (let k = 0; k < 3; k++) {
    let v = 0;
    for (let db = 0; db < 2; db++)
      for (let dg = 0; dg < 2; dg++)
        for (let dr = 0; dr < 2; dr++) {
          const w = (dr ? t[0] : 1 - t[0]) * (dg ? t[1] : 1 - t[1]) * (db ? t[2] : 1 - t[2]);
          v += w * at(lo[0] + dr, lo[1] + dg, lo[2] + db, k);
        }
    out[k] = v;
  }
  return out;
}

/**
 * The grade the world asks for (`planet.grade`): the URL of its own `.cube`
 * table, resolved against `baseUrl` (the view gives the planet
 * description's), or null for none. `auto` is none:
 * a world's colours stay as its author made them unless it asks for a look.
 * Null as well where the visitor's tier does not grade, or the URL is not one.
 * A URL with a scheme of its own is taken only over http(s); a relative one
 * is beside the world, however the world was served.
 */
export function gradeOf(hint: HintReader, allowed: boolean, baseUrl: string): string | null {
  if (!allowed) return null;
  const v = hint('planet.grade')?.trim();
  if (!v || v === 'auto' || v === 'none') return null;
  let url: URL;
  try {
    url = new URL(v, baseUrl);
  } catch {
    return null;
  }
  const relative = !/^[a-z][a-z0-9+.-]*:/i.test(v);
  return relative || url.protocol === 'https:' || url.protocol === 'http:' ? url.href : null;
}

/**
 * Whether the view softens its far ground from high up, where the tier draws it. The visitor's own
 * choice comes first (the settings menu's `graphics.focus`): `off` never softens, `on` always does. On
 * `auto`, the default, it follows the world: only where the world asks (`planet.focus="on"`); its `auto`
 * and `none` keep everything sharp, so no visitor gets blur nobody asked for.
 */
export function focusOf(hint: HintReader, allowed: boolean, visitor = 'auto'): boolean {
  if (!allowed || visitor === 'off') return false;
  return visitor === 'on' || hint('planet.focus')?.trim() === 'on';
}

const smoothstep = (a: number, b: number, x: number) => {
  const t = clamp((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
};

/** The focus for an eye `heightM` metres over the ground: how strongly the far ground softens, 0 to 1, and how far off, in metres, it starts to. Null for none. */
export function focusAt(heightM: number): { strength: number; distanceM: number } | null {
  const strength = smoothstep(FOCUS.fromM, FOCUS.fullM, heightM);
  if (!(strength > 0)) return null;
  return { strength, distanceM: heightM * FOCUS.perHeight };
}

/** How much of the widest blur a point `depthM` metres from the eye takes, 0 to 1, with the focus `focusM` metres off: none nearer than the focus. */
export function blurShare(depthM: number, focusM: number): number {
  if (!(depthM > focusM)) return 0;
  return 1 - focusM / depthM;
}

/** The widest blur's radius, in pixels, on a view `heightPx` tall. */
export function maxBlurPx(heightPx: number): number {
  return (FOCUS.maxPx * Math.max(1, heightPx)) / FOCUS.referenceHeightPx;
}
